import request from '@/router/axios';
export default {
  props: ["jobId"],
  data () {
    return {
      visible: false,
      dataForm: {
        id: ''
      },
      dataList: [],
      pageIndex: 1,
      pageSize: 10,
      totalPage: 0,
      dataListLoading: false
    }
  },
  methods: {
    init () {
      if(this.jobId){
        this.dataForm.id = this.jobId
      }else{
        this.dataForm.id = null
      }
      this.visible = true
      this.getDataList()
    },
    // 获取数据列表
    getDataList () {
      this.dataListLoading = true
      request({
        url: '/api/idevelop-data/sys/scheduleLog/list',
        method: 'get',
        params: {
          'current': this.pageIndex,
          'size': this.pageSize,
          'jobId': this.dataForm.id
        }
      }).then(({data}) => {
        if (data) {
          this.dataList = data.records
          this.totalPage = data.total
        } else {
          this.dataList = []
          this.totalPage = 0
        }
        this.dataListLoading = false
      })
    },
    // 每页数
    sizeChangeHandle (val) {
      this.pageSize = val
      this.pageIndex = 1
      this.getDataList()
    },
    // 当前页
    currentChangeHandle (val) {
      this.pageIndex = val
      this.getDataList()
    },
    // 失败信息
    showErrorInfo (id) {
      request({
        url: `/api/idevelop-data/sys/scheduleLog/info/${id}`,
        method: 'get',
        params: {}
      }).then(({data}) => {
        if (data) {
          this.$alert(data.log.error)
        } else {
          this.$message.error(data.msg)
        }
      })
    }
  }
}
